# =====================================================================
# === SECCION AGREGADA: FORMATO DE DATOS IGUAL AL BI (2026-07-16)   ===
# =====================================================================
# Esta seccion SOLO agrega formato de datos; no toca los queries ni la
# logica existente. Replica las transformaciones de tipo/limpieza que
# hace Power Query en el PBIX, para que la extraccion automatizada
# detecte y cuadre los mismos valores que el BI.
#
# Uso tipico desde el script principal (una sola linea despues de leer
# los datos):
#
#     df = aplicar_formato_bi(df)
#
# - Numeros: acepta Decimal, texto con comas de miles ("1,234.56"),
#   simbolos de moneda ("$", "Q", "S/", "L", "C$"), parentesis para
#   negativos, vacios/NULL, bytes, etc. Nada se pierde por formato.
# - Enteros: conteos e IDs quedan como enteros (sin ".0"), conservando
#   vacios (igual que el BI, que los maneja como Int64 con nulos).
# - Texto: bytes -> str, numeros -> texto sin ".0", nulos se conservan.
# - Ruta: se normaliza exactamente como lo hace el BI antes de cruzar
#   con la estructura (esa limpieza es la razon por la que el BI "si
#   detecta" rutas que el proceso automatizado no encontraba).

import re as _re
import unicodedata as _unicodedata
from decimal import Decimal as _Decimal

try:
    import pandas as _pd
except ImportError:  # pandas solo es necesario para aplicar_formato_bi
    _pd = None

_RE_MILES_COMA = _re.compile(r'^[-+]?\d{1,3}(,\d{3})+(\.\d+)?$')
_RE_MILES_PUNTO = _re.compile(r'^[-+]?\d{1,3}(\.\d{3})+$')
_VACIOS = ('', '-', 'null', 'none', 'nan', 'na', 'n/a', '#n/a', 's/d')


def limpiar_texto_bi(valor):
    """Equivalente a Text.Clean + Text.Trim de Power Query.

    Quita caracteres de control e invisibles (saltos, tabs, ZWSP),
    convierte espacio duro (NBSP) en espacio normal y recorta extremos.
    """
    if valor is None:
        return None
    if isinstance(valor, bytes):
        valor = valor.decode('utf-8', errors='ignore')
    if isinstance(valor, float) and valor != valor:  # NaN
        return None
    if not isinstance(valor, str):
        if isinstance(valor, float) and valor in (float('inf'), float('-inf')):
            return None
        if isinstance(valor, float) and valor == int(valor):
            valor = str(int(valor))
        else:
            valor = str(valor)
    valor = valor.replace('\xa0', ' ')
    valor = ''.join(c for c in valor if _unicodedata.category(c) not in ('Cc', 'Cf'))
    return valor.strip()


def convertir_numero_bi(valor):
    """Convierte cualquier representacion de numero a float (o None).

    Cubre los casos que hacian que el proceso automatizado "no
    detectara" valores que el BI si reconoce:
      Decimal(123.45)     -> 123.45      "1,234.56" -> 1234.56
      "$ 2,500"           -> 2500.0      "(150.25)" -> -150.25
      "1.234.567"         -> 1234567.0   "12,5"     -> 12.5
      "", "NULL", None    -> None        b"99.9"    -> 99.9
    Nota: con un solo punto se asume decimal (formato MySQL/BI en-US).
    """
    if valor is None:
        return None
    if isinstance(valor, bool):
        return float(valor)
    if isinstance(valor, (int, float)):
        if isinstance(valor, float) and valor != valor:  # NaN
            return None
        return float(valor)
    if isinstance(valor, _Decimal):
        return float(valor)
    if isinstance(valor, bytes):
        valor = valor.decode('utf-8', errors='ignore')
    txt = str(valor).strip().replace('\xa0', ' ')
    if txt.lower() in _VACIOS:
        return None
    negativo = txt.startswith('(') and txt.endswith(')')
    if negativo:
        txt = txt[1:-1]
    es_porcentaje = txt.rstrip().endswith('%')
    # quitar moneda, espacios y cualquier caracter no numerico
    txt = _re.sub(r'[^0-9,.\-+]', '', txt)
    if txt.strip('+-.,') == '':
        return None
    tiene_coma, tiene_punto = ',' in txt, '.' in txt
    if tiene_coma and tiene_punto:
        if txt.rfind(',') > txt.rfind('.'):
            txt = txt.replace('.', '').replace(',', '.')  # 1.234,56
        else:
            txt = txt.replace(',', '')                    # 1,234.56
    elif tiene_coma:
        if _RE_MILES_COMA.match(txt):
            txt = txt.replace(',', '')                    # 1,234
        else:
            txt = txt.replace(',', '.')                   # 12,5
    elif tiene_punto and _RE_MILES_PUNTO.match(txt) and txt.count('.') > 1:
        txt = txt.replace('.', '')                        # 1.234.567
    try:
        numero = float(txt)
    except ValueError:
        return None
    if negativo:
        numero = -abs(numero)
    if es_porcentaje:
        numero = numero / 100.0
    return numero


def convertir_entero_bi(valor):
    """Convierte a entero (conteos/IDs); None si no hay valor. Sin '.0'."""
    numero = convertir_numero_bi(valor)
    if numero is None:
        return None
    return int(round(numero))


def _texto_bi(valor):
    """Formato texto del BI: bytes->str, 123.0->'123', nulos intactos."""
    try:
        if valor is None or (isinstance(valor, float) and valor != valor):
            return None
        if _pd is not None and _pd.isna(valor):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(valor, bytes):
        valor = valor.decode('utf-8', errors='ignore')
    if isinstance(valor, _Decimal):
        valor = float(valor)
    if isinstance(valor, float) and valor == int(valor):
        valor = int(valor)
    return valor if isinstance(valor, str) else str(valor)


# ---------------------------------------------------------------------
# Tipos de dato por columna, replicados del modelo del BI
# "Cobranza Diaria Presico NV CIERRE 01.pbix". Se incluyen los nombres
# en TODAS sus etapas (crudo del query y columnas finales), de modo que
# aplicar_formato_bi() funcione sin importar en que punto se llame.
# ---------------------------------------------------------------------

_COLUMNAS_TEXTO_BI = [
    'Zona', 'Zona ', 'Ruta', 'Grupo', 'TIPO_DESEMBOLSO',
    'TIPO_DESEMBOLSO_NUEVO', 'TIPO_DESEMBOLSO_NUEVO_NW',
    'TIPO_DESEMBOLSO_NUEVO_NW ', 'Unidad de Negocio', 'Territorio',
    'Subdireccion', 'Sucursal', 'Marca', 'Base', 'País', 'Pais',
]

_COLUMNAS_ENTERAS_BI = [
    'coordinadora_id', 'dbc_cliente_id', 'numero_clientes_dia',
    'numero_clientes_dia_pagado', 'clientes_renovacion',
    'CAMBIO_COORDINAODRA', 'Faltas',
    # En este BI "dbc_cliente limpio" SI es entero (Int64), a diferencia
    # del BI LATAM donde queda como texto.
    'dbc_cliente limpio',
    # conteos intermedios que trae el query
    'AL_CORRIENTE', '#VENCIDO',
]

_CONTEOS_CRUDOS = ('numero_clientes_dia', 'numero_clientes_dia_pagado',
                   'clientes_renovacion')

# Dinero = todas las COLUMNAS_NUMERICAS que no son conteos + las
# calculadas del BI.
_COLUMNAS_DECIMALES_BI = [c for c in COLUMNAS_NUMERICAS if c not in _CONTEOS_CRUDOS]
_COLUMNAS_DECIMALES_BI += ['Cobranza_del_diaNW', 'Cobranza_con_atrasoNW',
    'Dif_Cob_dia vs Pago', 'cobranza_del_dia', 'diferencia_coranza_pagado',
    'saldo_devengado', 'AL_CORRIENTE_SALDO_DEVENGADO',
    '#VENCIDO_SALDO_DEVENGADO']

TIPOS_FORMATO_BI = {}
for _c in _COLUMNAS_DECIMALES_BI:
    TIPOS_FORMATO_BI[_c] = 'decimal'
for _c in _COLUMNAS_ENTERAS_BI:
    TIPOS_FORMATO_BI[_c] = 'entero'
for _c in _COLUMNAS_TEXTO_BI:
    TIPOS_FORMATO_BI[_c] = 'texto'

_RE_SEMANA_CONTEO = _re.compile(r'^\+?\d+(-\d+)?_SEMANA$')
_RE_SEMANA_SALDO = _re.compile(r'^\+?\d+(-\d+)?_SEMANA_SALDO_DEVENGADO$')


def _tipo_columna_bi(nombre):
    """Tipo BI de una columna; None si no se reconoce (se deja intacta)."""
    if not isinstance(nombre, str):
        return None
    tipo = TIPOS_FORMATO_BI.get(nombre) or TIPOS_FORMATO_BI.get(nombre.strip())
    if tipo:
        return tipo
    limpio = nombre.strip()
    if _RE_SEMANA_SALDO.match(limpio):
        return 'decimal'
    if _RE_SEMANA_CONTEO.match(limpio):
        return 'entero'
    return None


def normalizar_ruta_presico_mx(valor):
    """Ruta igual que el BI en la tabla PRESICO MX NV.

    El BI primero reemplaza el valor exacto 'MANZANILLO' por
    'MANZANILLO-P-R2' y despues aplica Text.Trim + Text.Clean. Esa
    limpieza es la que permite que el BI cruce rutas con la estructura
    aunque vengan con espacios o caracteres invisibles.
    """
    if valor is None:
        return None
    if isinstance(valor, bytes):
        valor = valor.decode('utf-8', errors='ignore')
    if not isinstance(valor, str):
        valor = str(valor)
    if valor == 'MANZANILLO':
        valor = 'MANZANILLO-P-R2'
    return limpiar_texto_bi(valor)


def aplicar_formato_bi(df, servidor=None, redondear=None):
    """Deja el DataFrame con los MISMOS formatos de dato que el BI.

    Se puede llamar en cualquier etapa (datos crudos por servidor o
    tabla final): detecta las columnas presentes por nombre y solo
    cambia formato, nunca valores ni logica.

    servidor:   nombre del servidor de SERVIDORES_PRESICO. Solo para
                'PRESICO MX NV' el BI limpia la columna Ruta (reemplazo
                MANZANILLO + trim + clean); para el resto la deja tal
                cual, y aqui se replica lo mismo.
    redondear:  None = igual que el BI (sin redondeo). Usa 2 para dejar
                los importes a 2 decimales al exportar.
    """
    if _pd is None:
        raise ImportError('aplicar_formato_bi requiere pandas instalado.')
    df = df.copy()
    for col in df.columns:
        tipo = _tipo_columna_bi(col)
        if tipo == 'decimal':
            serie = df[col].map(convertir_numero_bi)
            if redondear is not None:
                serie = serie.map(lambda x: None if x is None else round(x, redondear))
            df[col] = _pd.to_numeric(serie, errors='coerce')
        elif tipo == 'entero':
            df[col] = _pd.array([convertir_entero_bi(v) for v in df[col]], dtype='Int64')
        elif tipo == 'texto':
            df[col] = df[col].map(_texto_bi)
    if servidor == 'PRESICO MX NV' and 'Ruta' in df.columns:
        df['Ruta'] = df['Ruta'].map(normalizar_ruta_presico_mx)
    return df


# Alias descriptivo por si se importa junto con el modulo LATAM.
formatear_datos_presico = aplicar_formato_bi
